1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"syscall"
12	)
13	
14	// BuiltinVersionID identifies the built-in rule version, which reproduces
15	// the original fixed rules. It is always available, its parameters are
16	// queryable, and it cannot be overridden.
17	const BuiltinVersionID = "builtin"
18	
19	// ErrUnknownVersion reports a reference to a rule version that was never
20	// registered in the archive.
21	var ErrUnknownVersion = errors.New("unknown version")
22	
23	// ErrVersionConflict reports a re-registration of an existing version ID
24	// with different parameters.
25	var ErrVersionConflict = errors.New("version already registered with different parameters")
26	
27	// ErrCorruptVersion reports a version whose stored archive document no
28	// longer satisfies the registration rules: a rule object or a required
29	// field is missing or null, a value has the wrong type, or a severity or
30	// multiplier is out of range. The decoded struct cannot tell a missing
31	// field from an explicit zero value, so such an archive would otherwise
32	// run under silently zeroed parameters (a zero displacement multiplier
33	// even crashes detection). A comparison, review-range evaluation or replay
34	// naming a corrupt version is refused; the corrupt content is never
35	// replaced by the enabled version, the built-in rules or defaults.
36	var ErrCorruptVersion = errors.New("archived rule version is corrupted")
37	
38	// SandwichRule configures the sandwich rule: whether it runs and the
39	// severity of its conclusions.
40	type SandwichRule struct {
41		Enabled  bool `json:"enabled"`
42		Severity int  `json:"severity"`
43	}
44	
45	// DisplacementRule configures the displacement rule. A victim is flagged
46	// only when the previous swap's GasPrice strictly exceeds Multiplier times
47	// the victim's.
48	type DisplacementRule struct {
49		Enabled    bool `json:"enabled"`
50		Severity   int  `json:"severity"`
51		Multiplier int  `json:"multiplier"`
52	}
53	
54	// RuleSet is the complete declaration of both detection rules. Every
55	// version must declare both rules in full.
56	type RuleSet struct {
57		Sandwich     SandwichRule     `json:"sandwich"`
58		Displacement DisplacementRule `json:"displacement"`
59	}
60	
61	// RuleVersion is a named, immutable set of rule parameters.
62	type RuleVersion struct {
63		ID    string  `json:"id"`
64		Rules RuleSet `json:"rules"`
65	}
66	
67	// BuiltinVersion returns the version representing the original fixed
68	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
69	func BuiltinVersion() RuleVersion {
70		return RuleVersion{
71			ID: BuiltinVersionID,
72			Rules: RuleSet{
73				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
74				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
75			},
76		}
77	}
78	
79	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
80	// distinguish a missing field from an explicit zero value, and the decoder
81	// rejects unknown fields (including unknown rule names).
82	type toggleSpec struct {
83		Enabled  *bool `json:"enabled"`
84		Severity *int  `json:"severity"`
85	}
86	
87	type displacementSpec struct {
88		Enabled    *bool `json:"enabled"`
89		Severity   *int  `json:"severity"`
90		Multiplier *int  `json:"multiplier"`
91	}
92	
93	type versionSpec struct {
94		ID    *string `json:"id"`
95		Rules *struct {
96			Sandwich     *toggleSpec       `json:"sandwich"`
97			Displacement *displacementSpec `json:"displacement"`
98		} `json:"rules"`
99	}
100	
101	func parseEnabled(name string, v *bool) (bool, error) {
102		if v == nil {
103			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
104		}
105		return *v, nil
106	}
107	
108	func parseSeverity(name string, v *int) (int, error) {
109		if v == nil {
110			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
111		}
112		if *v < 1 || *v > 5 {
113			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
114		}
115		return *v, nil
116	}
117	
118	// ErrDuplicateField reports a JSON object in a registration spec that
119	// names the same field twice. Field names are compared the way JSON
120	// decoding matches struct fields, so two spellings the decoder folds
121	// together — differing only in case, like "severity" and "Severity", or
122	// using a compatibility character, like "ſeverity" (U+017F for s) — are
123	// also duplicates.
124	var ErrDuplicateField = errors.New("duplicate field in version spec")
125	
126	// ErrTrailingData reports non-whitespace content after the single JSON
127	// object that makes up a registration spec: a second object, another
128	// JSON value, an unmatched bracket or any other character.
129	var ErrTrailingData = errors.New("unexpected trailing data after version spec")
130	
131	// versionScanPolicy validates the shape of a rule version document with
132	// the shared scanner while keeping version-spec wording and sentinel
133	// errors.
134	var versionScanPolicy = specPolicy{
135		topObject:          "version spec",
136		known:              versionFields,
137		nested:             versionNestedTables,
138		rejectExactUnknown: true,
139		firstTokenError: func(err error) error {
140			if errors.Is(err, io.EOF) {
141				return errors.New("version spec must be a JSON object, got empty input")
142			}
143			return fmt.Errorf("invalid version spec: %w", err)
144		},
145		nonObject: func(tok json.Token) error {
146			if tok == nil {
147				return errors.New("version spec must be a JSON object, got null")
148			}
149			if d, ok := tok.(json.Delim); ok && d == '[' {
150				return errors.New("version spec must be a single JSON object, got array")
151			}
152			return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(tok))
153		},
154		wrap: func(err error) error {
155			return fmt.Errorf("invalid version spec: %w", err)
156		},
157		duplicate: func(obj, field, first, _ string) error {
158			return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, field, first)
159		},
160		trailing: versionTrailingData,
161	}
162	
163	// validateSpecStructure proves raw contains exactly one JSON object with
164	// no repeated fields anywhere in it, and nothing but whitespace around
165	// it. Keys are matched against the known fields of the version, rules,
166	// sandwich and displacement objects with the decoder's own field-name
167	// folding: "SEVERITY", "severity" and "ſeverity" (U+017F for s) all point
168	// at the same field and cannot share one object. Escaped key spellings
169	// are decoded before comparison, so "severity" cannot evade it.
170	func validateSpecStructure(raw []byte) error {
171		return scanJSONObject(raw, versionScanPolicy)
172	}
173	
174	// versionTrailingData names the first non-whitespace byte after the
175	// closed object, so an unmatched '}' or ']' is reported directly rather
176	// than as a syntax error; only whitespace may follow the object.
177	func versionTrailingData(raw []byte, offset int) error {
178		rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
179		if len(rest) > 0 {
180			return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
181		}
182		return nil
183	}
184	
185	var (
186		versionFields       = fieldTable("id", "rules")
187		rulesFields         = fieldTable("sandwich", "displacement")
188		sandwichFields      = fieldTable("enabled", "severity")
189		displacementFields  = fieldTable("enabled", "severity", "multiplier")
190		versionNestedTables = map[string]nestedObjectSpec{
191			"rules":        {rulesFields, "rules object"},
192			"sandwich":     {sandwichFields, "rules.sandwich"},
193			"displacement": {displacementFields, "rules.displacement"},
194		}
195	)
196	
197	// ParseRuleVersion validates a registration document. It must contain
198	// exactly one complete JSON object (leading and trailing whitespace
199	// allowed): a second object or value, an unmatched bracket or any other
200	// trailing character fails, and empty input, arrays and null are not
201	// specs. Duplicate fields are rejected at the top level, in rules and in
202	// each rule's parameters, including any spellings the decoder folds onto
203	// the same known field (case variants, U+017F for s, and the like). Missing fields, wrong types, out-of-range values and unknown
204	// rules or fields all fail with a reason.
205	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
206		if err := validateSpecStructure(raw); err != nil {
207			return RuleVersion{}, err
208		}
209		var spec versionSpec
210		dec := json.NewDecoder(bytes.NewReader(raw))
211		dec.DisallowUnknownFields()
212		if err := dec.Decode(&spec); err != nil {
213			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
214		}
215		if spec.ID == nil || *spec.ID == "" {
216			return RuleVersion{}, errors.New("id must be a non-empty string")
217		}
218		if spec.Rules == nil {
219			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
220		}
221		if spec.Rules.Sandwich == nil {
222			return RuleVersion{}, errors.New("rules.sandwich is required")
223		}
224		if spec.Rules.Displacement == nil {
225			return RuleVersion{}, errors.New("rules.displacement is required")
226		}
227		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
228		if err != nil {
229			return RuleVersion{}, err
230		}
231		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
232		if err != nil {
233			return RuleVersion{}, err
234		}
235		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
236		if err != nil {
237			return RuleVersion{}, err
238		}
239		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
240		if err != nil {
241			return RuleVersion{}, err
242		}
243		mult := spec.Rules.Displacement.Multiplier
244		if mult == nil {
245			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
246		}
247		if *mult < 2 || *mult > 100 {
248			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
249		}
250		return RuleVersion{
251			ID: *spec.ID,
252			Rules: RuleSet{
253				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
254				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
255			},
256		}, nil
257	}
258	
259	// findVersion resolves id against the built-in version and the archive's
260	// registered versions.
261	func findVersion(data archiveData, id string) (RuleVersion, error) {
262		if id == BuiltinVersionID {
263			return BuiltinVersion(), nil
264		}
265		for _, v := range data.Versions {
266			if v.ID == id {
267				return v, nil
268			}
269		}
270		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
271	}
272	
273	// intactVersion resolves id for a comparison and proves the version's
274	// stored archive document still satisfies every registration rule,
275	// re-validating the raw document with the same parser registrations pass.
276	// The decoded struct cannot do this: a missing enabled, severity or
277	// multiplier field unmarshals as the zero value and is indistinguishable
278	// from an explicitly declared one, and a wrong-typed field fails the
279	// whole-archive decode before any judgment can run. An explicitly
280	// declared false or any in-range value is valid; a missing or null field,
281	// a wrong type or an out-of-range number makes the version corrupt, and
282	// the failure names the version and the offending rule or field. The
283	// built-in version is constructed in code and always intact.
284	func intactVersion(versions []json.RawMessage, id string) (RuleVersion, error) {
285		if id == BuiltinVersionID {
286			return BuiltinVersion(), nil
287		}
288		for _, entry := range versions {
289			if !entryDeclaresID(entry, id) {
290				continue
291			}
292			v, err := ParseRuleVersion(entry)
293			if err != nil {
294				return RuleVersion{}, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, id, err)
295			}
296			return v, nil
297		}
298		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
299	}
300	
301	// entryDeclaresID reports whether the raw version entry carries the given
302	// id, recognising it the way the decoder folds field names — so "id", "ID"
303	// and "ıd"-style compatibility spellings all count — and inspecting every
304	// occurrence rather than decoding the object. A decayed document that
305	// repeats the id key ("id":"x","id":<target>, which a plain unmarshal folds
306	// onto the last value) is therefore still attributed to the registered
307	// version and judged as corruption by ParseRuleVersion, never dismissed as
308	// unknown. Entries that are not JSON objects, or whose id has no string
309	// occurrence equal to target, do not match.
310	func entryDeclaresID(entry json.RawMessage, id string) bool {
311		dec := json.NewDecoder(bytes.NewReader(entry))
312		first, err := dec.Token()
313		if err != nil {
314			return false
315		}
316		if d, ok := first.(json.Delim); !ok || d != '{' {
317			return false
318		}
319		// foldName folds to the smallest rune in each case-folding orbit, so the
320		// folded spelling of "id" is "ID"; fold the key the same way rather than
321		// comparing against the lowercase literal.
322		idField := foldName("id")
323		for dec.More() {
324			keyTok, err := dec.Token()
325			if err != nil {
326				return false
327			}
328			key, _ := keyTok.(string)
329			valTok, err := dec.Token()
330			if err != nil {
331				return false
332			}
333			if _, isDelim := valTok.(json.Delim); isDelim {
334				// Consume the container the id (or another key) points at; an
335				// object/array id is a wrong type, not a matching identity.
336				depth := 1
337				for depth > 0 {
338					tok, err := dec.Token()
339					if err != nil {
340						return false
341					}
342					if dd, ok := tok.(json.Delim); ok {
343						if dd == '{' || dd == '[' {
344							depth++
345						} else {
346							depth--
347						}
348					}
349				}
350				continue
351			}
352			if foldName(key) == idField {
353				if s, ok := valTok.(string); ok && s == id {
354					return true
355				}
356			}
357		}
358		return false
359	}
360	
361	// RegisterVersion validates raw as a rule version spec and stores it in the
362	// archive at dir. Re-registering the same ID with identical parameters
363	// succeeds without adding a version (created is false); the same ID with
364	// different parameters is rejected. The built-in version ID is reserved.
365	// Any failure leaves the archive untouched.
366	//
367	// Registration only ever adds the version this run submitted; it never
368	// repairs, completes, reorders or drops a stored declaration. The archive
369	// is therefore decoded with every registered version kept as its raw stored
370	// document, the same shape a replay or an enable uses: a corrupt sibling —
371	// a missing or null field, a wrong type, an out-of-range number, an unknown
372	// or duplicate field — is that version's damage, not whole-archive
373	// corruption, and neither blocks a legal new registration nor gets silently
374	// completed (a missing enabled would otherwise come back as an explicit
375	// false) or stripped of its unknown fields by one. When the submitted ID is
376	// already taken, the stored declaration must still satisfy the registration
377	// rules in full before any judgment about it: a corrupt one fails with
378	// ErrCorruptVersion naming the version and the offending rule or field —
379	// never created:false against the decayed parameters, never overwritten by
380	// the new ones, never misreported as a parameter conflict.
381	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
382		v, err = ParseRuleVersion(raw)
383		if err != nil {
384			return RuleVersion{}, false, err
385		}
386		if v.ID == BuiltinVersionID {
387			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
388		}
389		if err := os.MkdirAll(dir, 0o755); err != nil {
390			return RuleVersion{}, false, err
391		}
392		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
393		if err != nil {
394			return RuleVersion{}, false, err
395		}
396		defer lock.Close()
397	
398		data := replayArchiveDoc{Records: []record{}}
399		archiveRaw, err := readArchiveBytes(dir)
400		if err != nil {
401			return RuleVersion{}, false, err
402		}
403		if archiveRaw != nil {
404			if err := json.Unmarshal(archiveRaw, &data); err != nil {
405				return RuleVersion{}, false, fmt.Errorf("archive is corrupted: %w", err)
406			}
407		}
408		for _, entry := range data.Versions {
409			if !entryDeclaresID(entry, v.ID) {
410				continue
411			}
412			existing, perr := ParseRuleVersion(entry)
413			if perr != nil {
414				return RuleVersion{}, false, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, v.ID, perr)
415			}
416			if existing.Rules == v.Rules {
417				return existing, false, nil
418			}
419			return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
420		}
421		// The new version is appended as the exact document this run submitted
422		// and validated; every other section — the stored versions in order, the
423		// enabled marker, records, suppressions, alert records and reviews — is
424		// written back unchanged.
425		data.Versions = append(data.Versions, json.RawMessage(raw))
426		if err := writeArchiveAtomic(dir, data); err != nil {
427			return RuleVersion{}, false, err
428		}
429		return v, true, nil
430	}
431	
432	// EnableVersion makes id the archive's active version for later replays
433	// that name no explicit version. Before the marker changes, the selected
434	// version's stored archive document must still satisfy every registration
435	// rule in full — re-validated from its raw bytes with the same parser
436	// registrations pass — even when it is already the enabled version: the
437	// decoded struct cannot tell a decayed or wrong-typed field from an
438	// explicit value, so enabling a corrupt registered version fails with
439	// ErrCorruptVersion rather than succeeding under zeroed parameters and
440	// delaying the failure to the next replay. A version that was never
441	// registered stays an ErrUnknownVersion failure; the built-in version is
442	// constructed in code, needs no registration and is always intact. On
443	// success only the enabled marker changes: every other stored version is
444	// written back byte for byte (fields, values and order preserved, corrupt
445	// siblings included), and reports, suppressions, alert records and reviews
446	// are untouched. Any failure — corruption, an unreadable or busy archive,
447	// a failed write — leaves the archive unchanged.
448	func EnableVersion(dir, id string) (RuleVersion, error) {
449		if id == "" {
450			return RuleVersion{}, errors.New("version id must not be empty")
451		}
452		if err := os.MkdirAll(dir, 0o755); err != nil {
453			return RuleVersion{}, err
454		}
455		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
456		if err != nil {
457			return RuleVersion{}, err
458		}
459		defer lock.Close()
460	
461		// Decode with each registered version kept as its raw stored document,
462		// the same shape a replay uses: a wrong-typed field in one version is
463		// that version's corruption rather than whole-archive corruption, a
464		// corrupt sibling cannot block an intact candidate or builtin, and the
465		// versions not selected are written back verbatim — enabling a version
466		// never completes a missing field, fixes a value, reorders or drops an
467		// entry.
468		raw, err := readArchiveBytes(dir)
469		if err != nil {
470			return RuleVersion{}, err
471		}
472		data := replayArchiveDoc{Records: []record{}}
473		if raw != nil {
474			if err := json.Unmarshal(raw, &data); err != nil {
475				return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
476			}
477		}
478		// Validate the stored declaration before changing anything. An explicit
479		// enabled:false is a legal off state, but a disabled rule still has to
480		// carry complete, in-range parameters; a missing or null rule object or
481		// field, a wrong type, an out-of-range number, an unknown or duplicate
482		// field all fail here. intactVersion returns the built-in version for
483		// the built-in id and an unknown-version error for an id it cannot find.
484		v, err := intactVersion(data.Versions, id)
485		if err != nil {
486			return RuleVersion{}, err
487		}
488		if data.EnabledVersion == id {
489			return v, nil
490		}
491		data.EnabledVersion = id
492		if err := writeArchiveAtomic(dir, data); err != nil {
493			return RuleVersion{}, err
494		}
495		return v, nil
496	}
497	
498	// ListVersions returns the built-in version plus every version registered
499	// in the archive, along with the currently enabled version ID.
500	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
501		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
502			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
503		}
504		lock, err := lockArchive(dir, syscall.LOCK_SH)
505		if err != nil {
506			return nil, "", err
507		}
508		defer lock.Close()
509	
510		data, err := readArchive(dir)
511		if err != nil {
512			return nil, "", err
513		}
514		versions = append([]RuleVersion{BuiltinVersion()}, data.Versions...)
515		enabled = data.EnabledVersion
516		if enabled == "" {
517			enabled = BuiltinVersionID
518		}
519		return versions, enabled, nil
520	}
521	
522	// GetVersion returns one version's full parameters by ID.
523	func GetVersion(dir, id string) (RuleVersion, error) {
524		if id == BuiltinVersionID {
525			return BuiltinVersion(), nil
526		}
527		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
528			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
529		}
530		lock, err := lockArchive(dir, syscall.LOCK_SH)
531		if err != nil {
532			return RuleVersion{}, err
533		}
534		defer lock.Close()
535	
536		data, err := readArchive(dir)
537		if err != nil {
538			return RuleVersion{}, err
539		}
540		return findVersion(data, id)
541	}
