646			t.Fatalf("compared version wrong: %+v", result.ComparedVersion)
647		}
648		if len(result.Swaps) != 5 {
649			t.Fatalf("raw swap evidence missing: %+v", result.Swaps)
650		}
651		// 0xva: displacement under builtin, nothing under strict -> removed.
652		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xva" {
653			t.Fatalf("removed = %+v", result.Removed)
654		}
655		// 0xvb: sandwich under both, severity 3 -> 5: changed only, not added+removed.
656		if len(result.Changed) != 1 || result.Changed[0].TxHash != "0xvb" {
657			t.Fatalf("changed = %+v", result.Changed)
658		}
659		if result.Changed[0].Original.Severity != 3 || result.Changed[0].Compared.Severity != 5 {
660			t.Fatalf("change detail wrong: %+v", result.Changed[0])
661		}
662		if len(result.Added) != 0 {
663			t.Fatalf("added = %+v", result.Added)
664		}
665		// Both full conclusion sets are present.
666		if len(result.OriginalFindings) != 2 || len(result.ComparedFindings) != 1 {
667			t.Fatalf("findings sets wrong: %+v / %+v", result.OriginalFindings, result.ComparedFindings)
668		}
669		// Compare must not modify the archived report or the enabled version.
670		after, err := Query(dir, "1", "0xcmp")
671		if err != nil {
672			t.Fatal(err)
673		}
674		if after.Version.ID != BuiltinVersionID || len(after.Findings) != 2 || after.Findings[1].Severity != 2 {
675			t.Fatalf("compare modified the archived report: %+v", after)
676		}
677		_, enabled, _ := ListVersions(dir)
678		if enabled != BuiltinVersionID {
679			t.Fatalf("compare changed enabled version to %q", enabled)
680		}
681	}
682	
683	func TestCompareAddedAndSorted(t *testing.T) {
684		dir := t.TempDir()
685		// Builtin flags nothing (front gas 15 < 2*10? no: 15 > 20 false... 15 < 20, no displacement).
686		// A looser version (multiplier 1 not allowed; use severity-only change via multiplier 2 with
687		// front 25 > 20 for 0xvc, and front 21 > 20 for 0xva) — instead register a version with
688		// multiplier 2 but higher sandwich severity to also produce a change; keep it simple:
689		// builtin: no findings; strict2 (multiplier 2, but front 25/21 flagged): two added, hash-sorted.
690		input := `{"chainId":"1","blockHash":"0xadd","blockNumber":3,"swaps":[` +
691			`{"TxHash":"0xfz","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":25,"Index":0},` +
692			`{"TxHash":"0xvz","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},` +
693			`{"TxHash":"0xfa","Pool":"p2","Trader":"w","In":1,"Out":1,"GasPrice":21,"Index":2},` +
694			`{"TxHash":"0xva","Pool":"p2","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":3}]}`
695		reports := replay(t, dir, input)
696		if len(reports[0].Findings) != 2 {
697			t.Fatalf("setup: builtin should flag both (25>20, 21>20): %+v", reports[0].Findings)
698		}
699		// Compare against a version with multiplier 3: 25 > 30 false, 21 > 30 false -> both removed, sorted.
700		spec := `{"id":"x3","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":3}}}`
701		register(t, dir, spec)
702		result, err := Compare(dir, "1", "0xadd", "x3")
703		if err != nil {
704			t.Fatal(err)
705		}
706		if len(result.Removed) != 2 || result.Removed[0].TxHash != "0xva" || result.Removed[1].TxHash != "0xvz" {
707			t.Fatalf("removed not sorted by tx hash: %+v", result.Removed)
708		}
709		// Reverse direction: comparing a no-finding record against builtin adds them.
710		// Use the same block under x3 archived in a second archive for the added case.
711		dir2 := t.TempDir()
712		register(t, dir2, spec)
713		if _, err := ReplayWithVersion(strings.NewReader(input), dir2, "x3"); err != nil {
714			t.Fatal(err)
715		}
716		result2, err := Compare(dir2, "1", "0xadd", BuiltinVersionID)
717		if err != nil {
718			t.Fatal(err)
719		}
720		if len(result2.Added) != 2 || result2.Added[0].TxHash != "0xva" || result2.Added[1].TxHash != "0xvz" {
721			t.Fatalf("added not sorted by tx hash: %+v", result2.Added)
722		}
723		if result2.OriginalVersion.ID != "x3" {
724			t.Fatalf("original version wrong: %+v", result2.OriginalVersion)
725		}
726	}
727	
728	func TestCompareUnknown(t *testing.T) {
729		dir := t.TempDir()
730		replay(t, dir, sandwichInput)
731		if _, err := Compare(dir, "1", "0xmissing", BuiltinVersionID); !errors.Is(err, ErrUnknownBlock) {
732			t.Fatalf("got %v, want ErrUnknownBlock", err)
733		}
734		if _, err := Compare(dir, "1", "0xa", "ghost"); !errors.Is(err, ErrUnknownVersion) {
735			t.Fatalf("got %v, want ErrUnknownVersion", err)
736		}
737		if _, err := Compare(filepath.Join(dir, "nope"), "1", "0xa", BuiltinVersionID); !errors.Is(err, ErrUnknownBlock) {
738			t.Fatalf("got %v, want ErrUnknownBlock", err)
739		}
740	}
741	
742	func TestLegacyArchiveUsesBuiltinVersion(t *testing.T) {
743		dir := t.TempDir()
744		// Hand-write an archive in the pre-version format: no versions, no
745		// enabledVersion, records without a version field.
746		legacy := `{"records":[{"chainId":"1","blockHash":"0xleg","blockNumber":5,` +
747			`"swaps":[{"TxHash":"0xfront","Pool":"p1","Trader":"bot","In":500,"Out":480,"GasPrice":90,"Index":0},` +
748			`{"TxHash":"0xvictim","Pool":"p1","Trader":"user","In":200,"Out":188,"GasPrice":10,"Index":1},` +
749			`{"TxHash":"0xback","Pool":"p1","Trader":"bot","In":480,"Out":505,"GasPrice":80,"Index":2}],` +
750			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0xvictim","evidence":[` +
751			`{"TxHash":"0xfront","Pool":"p1","Trader":"bot","In":500,"Out":480,"GasPrice":90,"Index":0},` +
752			`{"TxHash":"0xvictim","Pool":"p1","Trader":"user","In":200,"Out":188,"GasPrice":10,"Index":1},` +
753			`{"TxHash":"0xback","Pool":"p1","Trader":"bot","In":480,"Out":505,"GasPrice":80,"Index":2}]}]}]}`
754		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
755			t.Fatal(err)
756		}
757		// Query: conclusions and evidence unchanged, version reported as builtin.
758		r, err := Query(dir, "1", "0xleg")
759		if err != nil {
760			t.Fatal(err)
761		}
762		if r.Version != BuiltinVersion() {
763			t.Fatalf("legacy record version = %+v, want builtin", r.Version)
764		}
765		if len(r.Findings) != 1 || r.Findings[0].Kind != "sandwich" || r.Findings[0].Severity != 3 ||
766			len(r.Findings[0].Evidence) != 3 {
767			t.Fatalf("legacy findings damaged: %+v", r.Findings)
768		}
769		// Compare against a registered version works on the legacy record.
770		register(t, dir, strictSpec)
771		result, err := Compare(dir, "1", "0xleg", "strict")
772		if err != nil {
773			t.Fatal(err)
774		}
775		if result.OriginalVersion != BuiltinVersion() || len(result.OriginalFindings) != 1 {
776			t.Fatalf("legacy compare wrong: %+v", result)
777		}
778		// Continued import judges new blocks under the enabled (builtin) rules
779		// and leaves the legacy record untouched.
780		reports := replay(t, dir, displacementInput)
781		if len(reports) != 1 || reports[0].Version.ID != BuiltinVersionID || len(reports[0].Findings) != 1 {
782			t.Fatalf("continued import wrong: %+v", reports)
783		}
784		data, err := readArchive(dir)
785		if err != nil {
786			t.Fatal(err)
787		}
788		if len(data.Records) != 2 {
789			t.Fatalf("records = %d, want 2", len(data.Records))
790		}
791		if data.Records[0].Version != nil {
792			t.Fatalf("legacy record was rewritten with a version: %+v", data.Records[0].Version)
793		}
794		if len(data.Records[0].Findings) != 1 || data.Records[0].Findings[0].Severity != 3 {
795			t.Fatalf("legacy findings modified: %+v", data.Records[0].Findings)
