24	// replayCorruptInput is one new block whose adjacent same-pool swaps hit
25	// displacement under any intact multiplier — the input shape that crashed
26	// detection when a stored multiplier decayed to zero.
27	var replayCorruptInput = cmpBlockLine("1", "0xnew", 8,
28		cmpSwap("0xn1", "p1", "w", 40, 0),
29		cmpSwap("0xn2", "p1", "u", 10, 1),
30	)
