55				reports, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC")
56				if err == nil {
57					t.Fatalf("corrupt version replayed successfully: %+v", reports)
58				}
59				if !errors.Is(err, ErrCorruptVersion) {
60					t.Fatalf("error = %v, want ErrCorruptVersion", err)
61				}
62				if errors.Is(err, ErrUnknownVersion) {
63					t.Fatalf("corruption misreported as unknown version: %v", err)
64				}
65				if !strings.Contains(err.Error(), "candC") {
66					t.Fatalf("error must name the selected version, got %v", err)
67				}
68				if !strings.Contains(err.Error(), tc.wantErr) {
69					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
70				}
71				if reports != nil {
72					t.Fatalf("a refused replay must return no reports, got %+v", reports)
73				}
