81	// TestReplayCorruptEnabledVersionRefused runs the same matrix against the
82	// archive's enabled version: a plain replay without --version selects it
83	// and must refuse it just the same. The version is enabled before the
84	// stored document is damaged.
85	func TestReplayCorruptEnabledVersionRefused(t *testing.T) {
86		for _, tc := range corruptVersionCases {
