89				if _, err := EnableVersion(dir, "candC"); err != nil {
90					t.Fatalf("EnableVersion: %v", err)
91				}
92				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
93					tc.mutate(t, ver)
94				})
95				before := readArchiveFile(t, dir)
96	
97				// Blank-lines-only input: the refusal is decided by the selected
98				// version, never by whether any input block triggers the rule.
99				_, err := Replay(strings.NewReader("\n  \n"), dir)
100				if !errors.Is(err, ErrCorruptVersion) {
101					t.Fatalf("error = %v, want ErrCorruptVersion", err)
102				}
