141				reports, err := ReplayWithVersion(strings.NewReader(tc.input), dir, "candC")
142				if !errors.Is(err, ErrCorruptVersion) {
143					t.Fatalf("error = %v, want ErrCorruptVersion", err)
144				}
145				if reports != nil {
146					t.Fatalf("partial success leaked reports: %+v", reports)
147				}
148				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
149					t.Fatalf("refused replay changed the archive")
150				}
