237			t.Fatalf("stored versions rewritten:\nbefore=%s\nafter =%s", before.Versions, after.Versions)
238		}
239		if before.EnabledVersion != after.EnabledVersion {
240			t.Fatalf("enabled marker changed: %q -> %q", before.EnabledVersion, after.EnabledVersion)
241		}
242		if !reflect.DeepEqual(before.Records, after.Records[:len(before.Records)]) {
243			t.Fatalf("existing records changed")
244		}
245		if len(after.Records) != len(before.Records)+1 {
