250	// TestReplayCorruptVersionPreservesArchive builds an archive holding every
251	// kind of state — reports, registered versions, the enabled marker, a
252	// suppression, alert processing records and manual review history — then
253	// proves a refused replay leaves the file byte-identical: the refusal
254	// never completes missing fields or fixes bad values in passing.
255	func TestReplayCorruptVersionPreservesArchive(t *testing.T) {
256		dir := t.TempDir()
257		register(t, dir, candidateVersionSpec)
258		if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); err != nil {
259			t.Fatal(err)
260		}
261		if _, err := EnableVersion(dir, "candC"); err != nil {
262			t.Fatal(err)
263		}
264		if _, _, err := RegisterSuppression(dir, []byte(
265			`{"id":"s1","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":1,"endHeight":100,"reason":"r"}`,
266		)); err != nil {
267			t.Fatal(err)
268		}
269		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
270			t.Fatal(err)
271		}
272		if _, err := SubmitReview(dir, ReviewSubmission{
273			ChainID: "1", BlockHash: "0xa", TxHash: "0xvictim", Kind: "displacement",
274			SubmissionID: "rev-1", Operator: "alice", Reason: "looks fine",
275			Status: ReviewStatusFalsePositive, ExpectedVersion: 0,
276		}); err != nil {
277			t.Fatal(err)
278		}
279	
280		// Damage the enabled version after all state exists: the displacement
281		// multiplier vanishes from the stored document.
282		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
283			delete(storedRule(t, ver, "displacement"), "multiplier")
284		})
285		before := readArchiveFile(t, dir)
286	
287		// Both selection paths refuse: the enabled version implicitly...
288		if _, err := Replay(strings.NewReader(replayCorruptInput), dir); !errors.Is(err, ErrCorruptVersion) {
289			t.Fatalf("enabled-version replay error = %v, want ErrCorruptVersion", err)
290		}
291		// ...and the same version named explicitly.
292		if _, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
293			t.Fatalf("explicit-version replay error = %v, want ErrCorruptVersion", err)
294		}
295	
296		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
297			t.Fatalf("refused replays changed the archive:\nbefore=%s\nafter =%s", before, after)
298		}
299	
300		// Every piece of prior state is still queryable and unchanged.
301		report, err := Query(dir, "1", "0xa")
302		if err != nil {
303			t.Fatal(err)
304		}
305		if report.Version.ID != "candC" || len(report.Findings) != 1 ||
306			report.Findings[0].Kind != "displacement" || report.Findings[0].Severity != 4 {
307			t.Fatalf("archived report changed: %+v", report)
308		}
309		history, err := ReviewHistoryQuery(dir, "1", "0xa", "0xvictim", "displacement")
310		if err != nil {
311			t.Fatal(err)
312		}
313		if history.Status != ReviewStatusFalsePositive || history.Version != 1 {
314			t.Fatalf("review history changed: %+v", history)
315		}
316		alerts, err := AlertHistory(dir, "1", "ops", 0, 100)
317		if err != nil {
318			t.Fatal(err)
319		}
320		if len(alerts) != 1 || alerts[0].Status != AlertStatusSuppressed {
321			t.Fatalf("alert records changed: %+v", alerts)
322		}
323	}
324	
325	// TestReplayCorruptVersionMultiplierZeroNoCrash pins the original crash:
326	// displacement enabled with the stored multiplier decayed to zero divided
327	// by zero as soon as one pool held two adjacent swaps. The replay must now
328	// fail cleanly with ErrCorruptVersion before detection ever runs.
329	func TestReplayCorruptVersionMultiplierZeroNoCrash(t *testing.T) {
330		dir := setupCorruptCompareArchive(t)
331		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
332			storedRule(t, ver, "displacement")["multiplier"] = 0
333		})
334		// candC's displacement rule is enabled; the input holds two adjacent
335		// same-pool swaps, the exact crash trigger.
336		_, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC")
337		if !errors.Is(err, ErrCorruptVersion) {
338			t.Fatalf("error = %v, want ErrCorruptVersion", err)
339		}
340		if !strings.Contains(err.Error(), "multiplier") {
341			t.Fatalf("error must name the multiplier field, got %v", err)
342		}
343	}
344	
345	// TestReplayLegacyArchiveWithoutVersions confirms pre-version archives are
346	// untouched by the integrity check: no versions section and no enabled
347	// marker still means the built-in rules, and a corrupt-free run behaves
348	// exactly as before.
349	func TestReplayLegacyArchiveWithoutVersions(t *testing.T) {
350		dir := t.TempDir()
351		legacy := `{"records":[{"chainId":"1","blockHash":"0old","blockNumber":5,` +
352			`"swaps":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
353			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
354			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
355			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
356			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
357			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
358			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
359		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
360			t.Fatal(err)
361		}
362		reports, err := Replay(strings.NewReader(replayCorruptInput), dir)
363		if err != nil {
364			t.Fatalf("legacy archive replay failed: %v", err)
365		}
