284				cmpSwap("0xg", "p2", "w", 23, 3),
285				cmpSwap("0xg-v", "p2", "u", 10, 4),
286			),
287		}, "\n")
288		replay(t, dir, input)
289		strict3 := `{"id":"m3","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":3}}}`
