3	// Regression coverage for enabling a rule version whose stored archive
4	// document has decayed since registration. `rules enable` must validate the
5	// selected version's actual stored declaration before it moves the enabled
6	// marker — the same proof a comparison, a review-range evaluation and a
7	// replay already demand — so a corrupt registered version is refused with
8	// ErrCorruptVersion (never reported unknown, never substituted with the
9	// current, built-in or default parameters), even when it is already the
10	// enabled version. A successful switch changes only the enabled marker:
11	// the other versions (corrupt siblings included), their fields and order,
12	// plus reports, suppressions, alert records and reviews are preserved.
13	
14	import (
15		"encoding/json"
16		"errors"
17		"os"
18		"path/filepath"
19		"reflect"
20		"strings"
21		"syscall"
22		"testing"
23	)
24	
25	// enableSkeleton reads the archive the way EnableVersion writes it:
26	// versions stay raw stored documents, so the sections can be compared
27	// byte for byte across a successful switch.
28	type enableSkeleton struct {
29		Records        []record           `json:"records"`
30		Versions       []json.RawMessage  `json:"versions"`
31		EnabledVersion string             `json:"enabledVersion"`
32		Suppressions   []Suppression      `json:"suppressions"`
33		AlertRecords   []ProcessingRecord `json:"alerts"`
34		Reviews        []ReviewObject     `json:"reviews"`
35	}
36	
37	func readEnableSkeleton(t *testing.T, dir string) enableSkeleton {
38		t.Helper()
39		var s enableSkeleton
40		if err := json.Unmarshal(readArchiveFile(t, dir), &s); err != nil {
41			t.Fatal(err)
42		}
43		return s
44	}
