46	// TestEnableCorruptVersionRefused runs the full corruption matrix against
47	// enabling a registered version: every way its stored document can stop
48	// satisfying the registration rules must fail with ErrCorruptVersion, name
49	// the version and the offending rule or field, and leave the archive —
50	// including the enabled marker — untouched.
51	func TestEnableCorruptVersionRefused(t *testing.T) {
52		for _, tc := range corruptVersionCases {
53			t.Run(tc.name, func(t *testing.T) {
54				dir := setupCorruptCompareArchive(t)
55				if _, err := EnableVersion(dir, "twin"); err != nil {
56					t.Fatalf("setup: EnableVersion twin: %v", err)
57				}
58				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
59					tc.mutate(t, ver)
60				})
61				before := readArchiveFile(t, dir)
62	
63				v, err := EnableVersion(dir, "candC")
64				if err == nil {
65					t.Fatalf("corrupt version enabled successfully: %+v", v)
66				}
67				if !errors.Is(err, ErrCorruptVersion) {
68					t.Fatalf("error = %v, want ErrCorruptVersion", err)
69				}
70				if errors.Is(err, ErrUnknownVersion) {
71					t.Fatalf("registered-but-corrupt version misreported as unknown: %v", err)
72				}
73				if !strings.Contains(err.Error(), "candC") {
74					t.Fatalf("error must name the selected version, got %v", err)
75				}
76				if !strings.Contains(err.Error(), tc.wantErr) {
77					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
78				}
79				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
80					t.Fatalf("refused enable changed the archive:\nbefore=%s\nafter =%s", before, after)
81				}
82				if got := readEnableSkeleton(t, dir).EnabledVersion; got != "twin" {
83					t.Fatalf("enabled marker changed to %q on refusal", got)
84				}
85			})
86		}
