234	// TestEnableCorruptDuplicateFieldRefused covers a decay registration could
235	// never have produced: a repeated field in the stored document. The raw
236	// bytes are patched directly because a JSON map cannot hold two keys.
237	func TestEnableCorruptDuplicateFieldRefused(t *testing.T) {
238		dir := setupCorruptCompareArchive(t)
239		path := filepath.Join(dir, archiveFileName)
240		raw := readArchiveFile(t, dir)
241		text := string(raw)
242		// Records precede the versions array and embed a full copy of candC in
243		// their "version" field, so anchor past "versions": the duplicate must
244		// land in the stored registration document, not in an archived record.
245		vsec := strings.Index(text, `"versions":`)
246		if vsec < 0 {
247			t.Fatal("versions section not found in archive")
248		}
249		at := strings.Index(text[vsec:], `"id": "candC"`)
250		if at < 0 {
251			t.Fatal("candC entry not found in versions section")
252		}
253		at += vsec
254		anchor := `"severity": 4,`
255		field := strings.Index(text[at:], anchor)
256		if field < 0 {
257			t.Fatal("candC severity field not found")
258		}
259		pos := at + field
260		patched := text[:pos] + `"severity": 4, ` + text[pos:]
261		if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
262			t.Fatal(err)
263		}
264		before := readArchiveFile(t, dir)
265	
266		_, err := EnableVersion(dir, "candC")
267		if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
268			t.Fatalf("duplicate-field document: err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
269		}
270		if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
271			t.Fatalf("error must name candC and severity, got %v", err)
272		}
273		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
274			t.Fatalf("refused enable changed the archive")
275		}
276	}
277	
278	// TestEnableCorruptDuplicateIDRefused covers a decayed document that also
279	// repeats its identity key: "id":"other" arrives last and a plain unmarshal
280	// would fold the entry onto "other", hiding candC behind an unknown-version
281	// error. The matcher must still attribute the entry to the registered
282	// version and refuse it as corruption, under either spelling.
283	func TestEnableCorruptDuplicateIDRefused(t *testing.T) {
284		dir := setupCorruptCompareArchive(t)
285		path := filepath.Join(dir, archiveFileName)
286		text := string(readArchiveFile(t, dir))
287		vsec := strings.Index(text, `"versions":`)
288		at := strings.Index(text[vsec:], `"id": "candC"`)
289		if at < 0 {
290			t.Fatal("candC entry not found in versions section")
291		}
292		pos := vsec + at
293		patched := text[:pos] + `"id": "candC", "id": "other", ` + text[pos+len(`"id": "candC",`):]
294		if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
295			t.Fatal(err)
296		}
297		before := readArchiveFile(t, dir)
298	
299		for _, asked := range []string{"candC", "other"} {
300			if _, err := EnableVersion(dir, asked); !errors.Is(err, ErrCorruptVersion) ||
301				errors.Is(err, ErrUnknownVersion) {
302				t.Fatalf("enabling %q against a duplicate-id document: %v", asked, err)
303			}
304		}
305		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
306			t.Fatalf("refused enable changed the archive")
307		}
308		// The intact twin is unaffected by the unidentifiable sibling.
309		if _, err := EnableVersion(dir, "twin"); err != nil {
310			t.Fatalf("intact twin blocked by corrupt sibling: %v", err)
311		}
312	}
313	
314	// TestEnableInvalidAndBusyArchiveReported covers the environment-level
315	// failures: an archive whose whole file is not valid JSON, or one locked by
316	// another process, must error clearly and leave the file alone.
317	func TestEnableInvalidAndBusyArchiveReported(t *testing.T) {
318		dir := t.TempDir()
319		register(t, dir, candidateVersionSpec)
320		path := filepath.Join(dir, archiveFileName)
321		if err := os.WriteFile(path, []byte(`{not json`), 0o644); err != nil {
322			t.Fatal(err)
323		}
324		before := readArchiveFile(t, dir)
325		if _, err := EnableVersion(dir, "candC"); err == nil ||
326			errors.Is(err, ErrUnknownVersion) || errors.Is(err, ErrCorruptVersion) {
327			t.Fatalf("invalid-JSON archive error = %v, want a whole-archive corruption error", err)
328		}
329		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
330			t.Fatalf("failed enable rewrote an invalid archive")
331		}
332	
333		// Busy archive: the lock failure is reported as such (fixture from the
334		// registration tests, version absent there so the lock is hit first).
335		busyDir := t.TempDir()
336		lock, err := os.OpenFile(filepath.Join(busyDir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
337		if err != nil {
338			t.Fatal(err)
339		}
340		defer lock.Close()
341		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
342			t.Fatal(err)
343		}
344		if _, err := EnableVersion(busyDir, "candC"); !errors.Is(err, ErrBusy) {
345			t.Fatalf("busy archive error = %v, want ErrBusy", err)
346		}
347	}
348	
349	// TestEnableLegacyArchiveAllowsBuiltin proves pre-version archives (no
350	// versions or enabledVersion fields) can still enable builtin, and the
351	// marker then drives plain replays without touching the legacy record.
352	func TestEnableLegacyArchiveAllowsBuiltin(t *testing.T) {
353		dir := t.TempDir()
354		legacy := `{"records":[{"chainId":"1","blockHash":"0old","blockNumber":5,` +
355			`"swaps":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
356			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
357			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
358			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
359			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
360			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
361			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
362		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
363			t.Fatal(err)
364		}
365		b, err := EnableVersion(dir, BuiltinVersionID)
366		if err != nil {
367			t.Fatalf("enabling builtin on a legacy archive failed: %v", err)
368		}
369		if b != BuiltinVersion() {
370			t.Fatalf("builtin parameters wrong: %+v", b)
371		}
372		if got := readEnableSkeleton(t, dir).EnabledVersion; got != BuiltinVersionID {
373			t.Fatalf("enabled marker = %q, want builtin", got)
374		}
375		reports := replay(t, dir, replayCorruptInput)
376		if len(reports) != 1 || reports[0].Version.ID != BuiltinVersionID ||
377			len(reports[0].Findings) != 1 || reports[0].Findings[0].Kind != "displacement" {
378			t.Fatalf("plain replay after enabling builtin misjudged: %+v", reports)
379		}
380		r, err := Query(dir, "1", "0old")
381		if err != nil {
382			t.Fatal(err)
383		}
384		if r.Version != BuiltinVersion() || len(r.Findings) != 1 {
385			t.Fatalf("legacy record modified on switch: %+v", r)
386		}
387	
388		// An empty archive (no file yet) accepts builtin the same way.
389		fresh := t.TempDir()
390		if _, err := EnableVersion(fresh, BuiltinVersionID); err != nil {
391			t.Fatalf("enabling builtin before any archive exists failed: %v", err)
392		}
393	}
394	
395	// TestEnableSwitchPreservesAllPriorState builds an archive holding every
396	// kind of state, then switches to an intact version and proves only the
397	// enabled marker changed: stored versions survive verbatim, and reports,
398	// suppressions, alert processing records and manual reviews keep their
399	// historical conclusions — nothing is re-detected or rewritten.
400	func TestEnableSwitchPreservesAllPriorState(t *testing.T) {
401		dir := t.TempDir()
402		register(t, dir, candidateVersionSpec)
403		register(t, dir, twinVersionSpec)
404		if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); err != nil {
405			t.Fatal(err)
406		}
407		if _, err := EnableVersion(dir, "candC"); err != nil {
408			t.Fatal(err)
409		}
410		if _, _, err := RegisterSuppression(dir, []byte(
411			`{"id":"s1","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":1,"endHeight":100,"reason":"r"}`,
412		)); err != nil {
413			t.Fatal(err)
414		}
415		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
416			t.Fatal(err)
417		}
418		if _, err := SubmitReview(dir, ReviewSubmission{
419			ChainID: "1", BlockHash: "0xa", TxHash: "0xvictim", Kind: "displacement",
420			SubmissionID: "rev-1", Operator: "alice", Reason: "looks fine",
421			Status: ReviewStatusFalsePositive, ExpectedVersion: 0,
422		}); err != nil {
423			t.Fatal(err)
424		}
425		before := readEnableSkeleton(t, dir)
426	
427		if v, err := EnableVersion(dir, "twin"); err != nil || v.ID != "twin" {
428			t.Fatalf("switch to twin: v=%+v err=%v", v, err)
429		}
430		// Switching to the already-enabled marker semantics: re-enabling twin
431		// now is a no-write validation path and still succeeds.
432		if _, err := EnableVersion(dir, "twin"); err != nil {
433			t.Fatalf("re-enabling the current intact version failed: %v", err)
434		}
435	
436		after := readEnableSkeleton(t, dir)
437		if !reflect.DeepEqual(before.Versions, after.Versions) {
438			t.Fatalf("switch rewrote stored versions:\nbefore=%s\nafter =%s", before.Versions, after.Versions)
439		}
440		if after.EnabledVersion != "twin" {
441			t.Fatalf("enabled marker = %q, want twin", after.EnabledVersion)
442		}
443		if !reflect.DeepEqual(before.Records, after.Records) {
444			t.Fatalf("historical reports changed on switch: %+v vs %+v", before.Records, after.Records)
445		}
446		if !reflect.DeepEqual(before.Suppressions, after.Suppressions) {
447			t.Fatalf("suppressions changed on switch")
448		}
449		if !reflect.DeepEqual(before.AlertRecords, after.AlertRecords) {
450			t.Fatalf("alert records changed on switch")
451		}
452		if !reflect.DeepEqual(before.Reviews, after.Reviews) {
453			t.Fatalf("manual reviews changed on switch")
454		}
455	
456		// Historical conclusions keep their candC verdict and are not re-judged.
457		report, err := Query(dir, "1", "0xa")
458		if err != nil {
459			t.Fatal(err)
460		}
461		if report.Version.ID != "candC" || len(report.Findings) != 1 ||
462			report.Findings[0].Kind != "displacement" || report.Findings[0].Severity != 4 {
463			t.Fatalf("archived report re-detected on switch: %+v", report)
464		}
465		history, err := ReviewHistoryQuery(dir, "1", "0xa", "0xvictim", "displacement")
466		if err != nil {
467			t.Fatal(err)
468		}
469		if history.Status != ReviewStatusFalsePositive || history.Version != 1 {
470			t.Fatalf("review history changed on switch: %+v", history)
471		}
472		alerts, err := AlertHistory(dir, "1", "ops", 0, 100)
473		if err != nil {
474			t.Fatal(err)
475		}
476		if len(alerts) != 1 || alerts[0].Status != AlertStatusSuppressed {
477			t.Fatalf("alert history changed on switch: %+v", alerts)
478		}
479	
480		// A new block without an explicit version is judged under twin now.
481		input := cmpBlockLine("1", "0xnew", 11,
482			cmpSwap("0xn1", "p1", "w", 40, 0),
483			cmpSwap("0xn2", "p1", "u", 10, 1),
484		)
485		reports, err := Replay(strings.NewReader(input), dir)
486		if err != nil {
487			t.Fatal(err)
488		}
489		if len(reports) != 1 || reports[0].Version.ID != "twin" {
490			t.Fatalf("new block did not replay under the newly enabled version: %+v", reports)
491		}
492	}
