1	package main
2	
3	// End-to-end regression coverage for the `replay` command against a
4	// corrupt archived rule version: the run must refuse the whole import with
5	// a clean corruption error — naming the version and the offending rule or
6	// field — before any report is printed or any block is archived, whether
7	// the version was selected with --version or through the archive's enabled
8	// marker. A corrupt version is never misreported as unknown, and a corrupt
9	// sibling never blocks an intact one.
10	
11	import (
12		"encoding/json"
13		"os"
14		"path/filepath"
15		"reflect"
16		"strings"
17		"testing"
18	
19		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
20	)
21	
22	// setupReplayCLIArchive registers candC (sandwich off, displacement
23	// severity 4 multiplier 2), archives one block under it and enables it.
24	func setupReplayCLIArchive(t *testing.T) (dir string) {
25		t.Helper()
26		dir = t.TempDir()
27		const candC = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
28		if _, _, err := mevwatch.RegisterVersion(dir, []byte(candC)); err != nil {
29			t.Fatalf("RegisterVersion: %v", err)
30		}
31		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
32		if err := os.WriteFile(inputPath, []byte(cliBlockLine("1", "0xblk", 7,
33			cliSwapRecord("0xf", "p1", "w", 40, 0),
34			cliSwapRecord("0xv", "p1", "u", 10, 1),
35		)+"\n"), 0o644); err != nil {
36			t.Fatal(err)
37		}
38		if _, err := mevwatch.ReplayFileWithVersion(inputPath, dir, "candC"); err != nil {
39			t.Fatalf("ReplayFileWithVersion: %v", err)
40		}
41		if _, err := mevwatch.EnableVersion(dir, "candC"); err != nil {
42			t.Fatalf("EnableVersion: %v", err)
43		}
44		return dir
45	}
46	
47	// writeReplayInput writes one new block whose two adjacent same-pool swaps
48	// hit displacement under any intact multiplier — the input shape that
49	// crashed detection when a stored multiplier decayed to zero.
50	func writeReplayInput(t *testing.T) string {
51		t.Helper()
52		inputPath := filepath.Join(t.TempDir(), "new.jsonl")
53		if err := os.WriteFile(inputPath, []byte(cliBlockLine("1", "0xnew", 8,
54			cliSwapRecord("0xn1", "p1", "w", 40, 0),
55			cliSwapRecord("0xn2", "p1", "u", 10, 1),
56		)+"\n"), 0o644); err != nil {
57			t.Fatal(err)
58		}
59		return inputPath
60	}
61	
62	func TestCLIReplayCorruptVersion(t *testing.T) {
63		dir := setupReplayCLIArchive(t)
64		inputPath := writeReplayInput(t)
65		// The stored candC document loses its displacement multiplier: valid
66		// JSON, but no longer a complete rule declaration.
67		corruptStoredVersion(t, dir, "candC", func(ver map[string]any) {
68			delete(ver["rules"].(map[string]any)["displacement"].(map[string]any), "multiplier")
69		})
70	
71		// Explicit selection refuses the whole import before any report.
72		res := runCLI(t, "replay", "--version", "candC", inputPath, dir)
73		if res.exitCode != 1 {
74			t.Fatalf("exit = %d, want 1; stdout=%q stderr=%q", res.exitCode, res.stdout, res.stderr)
75		}
76		if res.stdout != "" {
77			t.Fatalf("corrupt version must print no report JSON, got %q", res.stdout)
78		}
79		for _, want := range []string{"corrupt", "candC", "multiplier"} {
80			if !strings.Contains(res.stderr, want) {
81				t.Fatalf("stderr = %q, want substring %q", res.stderr, want)
82			}
83		}
84		// A clean message, never a panic with a Go stack.
85		if strings.Contains(res.stderr, "goroutine") || strings.Contains(res.stderr, "runtime error") {
86			t.Fatalf("replay crashed instead of failing cleanly: %q", res.stderr)
87		}
88	
89		// The enabled marker selects the same corrupt version for a plain
90		// replay: same refusal.
91		res = runCLI(t, "replay", inputPath, dir)
92		if res.exitCode != 1 || res.stdout != "" ||
93			!strings.Contains(res.stderr, "corrupt") || !strings.Contains(res.stderr, "candC") {
94			t.Fatalf("enabled-version failure shape wrong: exit=%d stdout=%q stderr=%q",
95				res.exitCode, res.stdout, res.stderr)
96		}
97	
98		// An unregistered version stays a plain unknown-version failure.
99		res = runCLI(t, "replay", "--version", "nope", inputPath, dir)
100		if res.exitCode != 1 || !strings.Contains(res.stderr, "unknown version: nope") ||
101			strings.Contains(res.stderr, "corrupt") {
102			t.Fatalf("unknown version failure changed shape: exit=%d stderr=%q", res.exitCode, res.stderr)
103		}
104	
105		// The corrupt sibling does not contaminate the built-in version.
106		res = runCLI(t, "replay", "--version", "builtin", inputPath, dir)
107		if res.exitCode != 0 {
108			t.Fatalf("replay under builtin failed: %d %q", res.exitCode, res.stderr)
109		}
110		if !strings.Contains(res.stdout, `"blockHash":"0xnew"`) {
111			t.Fatalf("builtin replay must print the new block's report, got %q", res.stdout)
112		}
113	
114		// The refusals never touched the archive; only the final successful
115		// builtin replay appended its block. Verify the corrupt version
116		// document survived verbatim instead: no missing field was completed,
117		// no bad value fixed, and the enabled marker still names candC.
118		var doc struct {
119			Versions []struct {
120				ID    string `json:"id"`
121				Rules struct {
122					Displacement map[string]any `json:"displacement"`
123				} `json:"rules"`
124			} `json:"versions"`
125			EnabledVersion string `json:"enabledVersion"`
126		}
127		after, err := os.ReadFile(filepath.Join(dir, "archive.json"))
128		if err != nil {
129			t.Fatal(err)
130		}
