465	// corruptStoredVersion rewrites the stored archive document of one
466	// registered version, simulating an archive that is still valid JSON but
467	// whose registered version no longer satisfies the registration rules.
468	func corruptStoredVersion(t *testing.T, dir, id string, mutate func(ver map[string]any)) {
469		t.Helper()
470		archivePath := filepath.Join(dir, "archive.json")
471		raw, err := os.ReadFile(archivePath)
472		if err != nil {
473			t.Fatal(err)
474		}
475		var doc map[string]any
476		if err := json.Unmarshal(raw, &doc); err != nil {
477			t.Fatal(err)
478		}
479		for _, entry := range doc["versions"].([]any) {
480			ver := entry.(map[string]any)
481			if ver["id"] == id {
482				mutate(ver)
483			}
484		}
485		out, err := json.MarshalIndent(doc, "", "  ")
486		if err != nil {
487			t.Fatal(err)
488		}
489		if err := os.WriteFile(archivePath, out, 0o644); err != nil {
490			t.Fatal(err)
491		}
492	}
