		t.Fatal(err)
	}
	_, err := GetVersion(dir, "twin")
	if err == nil {
		t.Fatal("unparseable archive produced a version")
	}
	if errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("whole-archive failure misreported as a corrupt version: %v", err)
	}
